COMMENT ON TABLE  "SEPA_SYSTEM_EVENT_NOTE" IS 'Table is used to store admi.004 (SystemEventNotification) message.';


COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_CODE" IS 'INS for insertion of new un-availability message. DEL for deleting of a previous inserted message';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_DESCRIPTION" IS 'Free text for Participant ';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_TIME" IS 'Date and time at which the event occurred.';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_PARAMETER1" IS 'Unique ID for BIC. ';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_PARAMETER2" IS 'Unavailable for BIC';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_PARAMETER3" IS 'Start date and time of unavailability';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_PARAMETER4" IS 'End date and time of unavailability';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_PARAMETER5" IS 'Optional field to indicate unavailable product';

COMMENT ON COLUMN  "SEPA_SYSTEM_EVENT_NOTE"."EVENT_PARAMETER6" IS 'ID of unavailable party, according to naming convention managed by a different system.';

