column47:
Create a new procedure"{*}MDM_AGREEMENT_SWIFT{*}" in "{*}PAYMENTS_AGREEMENTS_MDM.MDM_PAYLOAD_MESSAGE_GENERATION{*}" (PAYRUN-1515) to generate payload message for Homebank product in CORE DBs (LT, EE, LV) 

The new procedure must be able to:
 * Generate [Agreement Summary payloads|https://wiki.swedbank.net/pages/viewpage.action?pageId=842727454#expand-Engagementpayload] messages based on input parameters and add it into queue "{*}PAYMENTS_AGREEMENTS_MDM.MDM_MESSAGES{*}" (PAYRUN-1390)

Input parameters:
 * i_operation - VARCHAR2, possible values: INSERT, UPDATE, DELETE;
 * i_agreement_id - NUMBER, crebit.swr_contract.cnt_number
 * i_status - VARCHAR2, crebit.swr_contract.status
 * i_dt_from - DATE, crebit.swr_contract.start_date
 * i_dt_till - DATE, crebit.swr_contract.end_date
 * i_last_updated_time - TIMESTAMP, cast crebit.swr_contract.changed_date to timestamp
 * i_customer_id - VARCHAR2, crebit.swr_contract.customer_id

On input parameter *i_operation* value *INSERT* or *UPDATE* generate the following payload message:
{code:java}
{
  "sourceSystemId": "",         // STATIC VALUE - (string) - use "PAYMENTS" as value 
  "correlationId": "",          // DYNAMIC VALUE - (string) - use "YYYYMMDD_HHMMSS_CREBIT.SWR_CONTRACT[CNT_NUMBER]", Format:20240509_110414_6940174571   
  "instanceId": "",             // DYNAMIC VALUE - (string)- use "EE", "LT", "LV" as value based on engagement origin country context
  "type": "",                   // STATIC VALUE - (string) - use "ENGAGEMENT" as value
  "lastModifiedTimestamp": ,    // DYNAMIC VALUE - (long timestamp) - use CREBIT.SWR_CONTRACT CHANGED_DATE table column value, format: unix timestamp milliseconds, sys_extract_utc
  "operation": "",              // DYNAMIC VALUE - (string) depends on type of event trigger captured, possible values: "INSERT", "UPDATE"
  "payload": {                  // (object) Details of the change
    "engagementSourceRef": "",  // DYNAMIC VALUE - (string) - use "CREBIT.SWR_CONTRACT[CNT_NUMBER]",  Format: <shema_name>.<table_name>[<unique record_id>]         
    "type": "",                 // STATIC VALUE - (string) - use "SWIFT_AGREEMENT" as value
    "status": "",               // DYNAMIC VALUE - (string) - use CREBIT.SWR_CONTRACT STATUS table column value
    "nr": "",                   // DYNAMIC VALUE - (string) - use CREBIT.SWR_CONTRACT CNT_NUMBER table column value      
    "startDate": ,              // DYNAMIC VALUE - (long timestamp) - use CREBIT.SWR_CONTRACT START_DATE, format: unix timestamp milliseconds, sys_extract_utc
    "endDate": ,                // DYNAMIC VALUE - (long timestamp) - use CREBIT.SWR_CONTRACT END_DATE, format: unix timestamp milliseconds, sys_extract_utc
    "partyRoles": [             // (list) List of all party roles related to this engagement
      {
        "roleSourceRef": "",    // DYNAMIC VALUE - (string) - use CREBIT.SWR_CONTRACT[CNT_NUMBER] Format: <shema_name>.<table_name>[<unique record_id>].
        "partyId": "",          // DYNAMIC VALUE - (string) - use CREBIT.SWR_CONTRACT CUSTOMER_ID
        "role": "",             // STATIC VALUE - (string) - use "SWIFT_BENEFICIARY" as value
        "startDate": ,          // DYNAMIC VALUE - (long timestamp) - use CREBIT.SWR_CONTRACT START_DATE table column value, format: unix timestamp milliseconds, sys_extract_utc
        "endDate":              // DYNAMIC VALUE - (long timestamp) - use CREBIT.SWR_CONTRACT END_DATE table column value, format: unix timestamp milliseconds, sys_extract_utc
     }
    ]
  }
}{code}
On input parameter *i_operation* value *DELETE* generate the following payload message: 
{code:java}
{
  "sourceSystemId": "",         // STATIC VALUE - (string) - use "PAYMENTS" as value 
  "correlationId": "",          // DYNAMIC VALUE - (string) - use "YYYYMMDD_HHMMSS_CREBIT.SWR_CONTRACT[CNT_NUMBER]", Format:20240509_110414_6940174571   
  "instanceId": "",             // DYNAMIC VALUE - (string)- use "EE", "LT", "LV" as value based on engagement origin country context
  "type": "",                   // STATIC VALUE - (string) - use "ENGAGEMENT" as value
  "lastModifiedTimestamp": ,    // DYNAMIC VALUE - (long timestamp) - use (TBD), format: unix timestamp milliseconds
  "operation": "",              // STATIC VALUE - (string) possible value: "DELETE"
  "payload": {                  // (object) Details of the change
    "engagementSourceRef": ""  // DYNAMIC VALUE - (string) - use "CREBIT.SWR_CONTRACT[CNT_NUMBER]",  Format: <shema_name>.<table_name>[<unique record_id>]         
  }
}{code}
----
 

*Examples* from other product areas

*UPDATE* operation (ENGAGEMENT payload example from Leasing):
{code:java}
{
   "sourceSystemId":"LEASING",
   "correlationId":"969720186_24052024112930_0XZVJ",
   "instanceId":"LV",
   "type":"ENGAGEMENT",
   "lastModifiedTimestamp":1716539370000,
   "operation":"UPDATE",
   "payload":{
      "engagementSourceRef":"HCL.OFR_OFFER_MAIN[969720186]",
      "type":"LEASING_OFFER",
      "status":"OFR_WTN",
      "nr":"PIED1665438",
      "startDate":1716498000000,
      "endDate":null,
      "partyRoles":[
         {
            "partyId":"13446236",
            "role":"ENGAGEMENT_OWNER",
            "startDate":1716498000000,
            "endDate":null,
            "disposalDate":null,
            "roleSourceRef":"HCL.OFR_PARTY_ROLE[969728981]",
            "sourceLastModifiedDtime":null
         }
      ]
   }
}{code}
*INSERT* operation (ENGAGEMENT payload example from Factoring):
{code:java}
{
  "sourceSystemId": "CREDITMEMO",
  "correlationId": "e24a277a-7546-4575-b097-357a4300d142",
  "instanceId": "EE",
  "type": "ENGAGEMENT",
  "lastModifiedTimestamp": 1716538602932,
  "operation": "INSERT",
  "payload": {
    "engagementSourceRef": "CREDIT_MEMO.MEMO[51503]",
    "type": "MEMO",
    "status": "APPROVED",
    "nr": "51503",
    "startDate": 1515155415722,
    "endDate": 1516001063089,
    "partyRoles": [
      {
        "partyId": "54828",
        "role": "COLLATERAL_ASSET_OWNER",
        "startDate": 1516001063089,
        "endDate": 1516001063089,
        "disposalDate": null,
        "roleSourceRef": "CREDIT_MEMO.OWNERSHIP[13890139]",
        "sourceLastModifiedDtime": 1716538603375
      }
    ]
  }
}{code}
 

DELETE operation (ENGAGEMENT payload example from Factoring):

 
{code:java}
