column47:
GRPC endpoint ValidateAndEnrich is removing some values which are necessary for Flow Manager(FLM).  FLM does the GRPC API request using full PODM attributes and once the response is received back it overwrites current value of PODM JSON with the one received from API. ValidateAndEnrich is meant to modify/add/remove values and FLM treats response as source of true. Despite that, some attribute values necessary for correct processing in FLM are being removed in the API response. Below are the ones currently identified. These values must be returned same as in the request.

*1.Missing fields in the response:*
*/bkIntPrtryInf/procgInf/hldrChnlCd*
REQUEST:
          "hldrChnlCd":

{             "value": "THN"           }

,
 
RESPONSE:
            "hldrChnlCd":

{                 "value": ""             }

,
 
 
*2.Missing fields in the response:*
*/bkIntPrtryInf/pties/dbtr/acctIsOurs*
*/bkIntPrtryInf/pties/dbtr/intlNm*
*/bkIntPrtryInf/pties/cdtr/acctIsOurs*
 
REQUEST:
      "pties": {
          "dbtr": {
              "acctIsOurs":

{                 "value": "0"               }

,
              "cstmrId":

{                 "value": "B2222211"               }

,
              "intlNm":

{                 "value": "JAROSDDDDDDLAV TEDDDDSTXXX"               }

          },
          "cdtr": {
              "acctIsOurs":

{                 "value": "-2"               }

          }
      },
 
RESPONSE:
        "pties": {
            "cdtr": {
                "acctIsOurs":

{                     "value": ""                 }

,
                "cstmrId":

{                     "value": ""                 }

,
                "intlNm":

{                     "value": ""                 }

            },
            "dbtr": {
                "acctIsOurs":

{                     "value": ""                 }

,
                "cstmrId":

{                     "value": "B2222211"                 }

,
                "intlNm":

{                     "value": ""                 }

